type Id = integer;
const id: Id = 3;

const a: integer[] = [1, 2];
const b: string[] = ["x"];
const c: integer[][] = [[1], [2, 3]];

/* Used with interfaces or object shapes, for example: */
type Labeled = { id: integer } & { name: string };
const v: Labeled = { id: 1, name: "a" };

const o: { host: string, port?: integer } = { host: "h" };
const handlers: { run: (a: integer) => integer } = {
    run: function (a: integer): integer { return a; }
};

const f: (a: integer) => integer = function (a: integer): integer {
    return a + 1;
};
assert(f(2) === 3);

const pred: (...values: any) => boolean = function (n) {
    return n % 2 === 0;
};

const n: integer = 1;
let s: string = "a";
function add1(a: integer): integer {
    return a + 1;
}

interface Base {
    id: integer
};
interface Person extends Base {
    name: string,
    age?: integer
};
const p: Person = { id: 1, name: "a" };

/* Environment flags (host or flag_set) */
flag_set(["compile:typeCheck"], true);
flag_set(["compile:strict"], true);

/* Or the same options in this script only */
#compile typeCheck;
#compile typeCheck noImplicitAny;
#compile typeCheckCompileOnly;
#compile strictNullChecks;
#compile strict;
#compile noOptimize;
#compile noTypeCheck;

#compile typeCheck;

